-- Report ID : RPT_405
-- Report    : Lead Time Pickup Validation
-- Module    : Replenishment
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT      im.DEPT                                             AS dept_no,     d.DEPT_NAME                                         AS dept_name,     im.CLASS                                            AS class_no,     c.CLASS_NAME                                        AS class_name,     im.SUBCLASS                                         AS subclass_no,     sc.SUB_NAME                                         AS subclass_name,      im.ITEM                                             AS item_id,     im.ITEM_DESC                                        AS item_description,     im.STANDARD_UOM                                     AS uom,     im.STATUS                                           AS item_status,      ril.LOCATION                                        AS location_id,     il.LOC_TYPE                                         AS loc_type,     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                 AS location_name,     CASE il.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                 AS location_type_desc,     il.STATUS                                           AS item_loc_status,      ril.REPL_METHOD                                     AS repl_method,     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'DI' THEN 'Dynamic - Issues'         WHEN 'S'  THEN 'Dynamic - Seasonal'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'SO' THEN 'Store Orders'         WHEN 'T'  THEN 'Time Supply'         WHEN 'TI' THEN 'Time Supply - Issues'         WHEN 'E'  THEN 'Time Supply - Seasonal'         ELSE ril.REPL_METHOD     END                                                 AS repl_method_desc,     ril.STOCK_CAT                                       AS stock_category,     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'         ELSE ril.STOCK_CAT     END                                                 AS stock_category_desc,     ril.REPL_ORDER_CTRL                                 AS order_control,     CASE ril.REPL_ORDER_CTRL         WHEN 'A' THEN 'Automatic'         WHEN 'B' THEN 'Buyer Worksheet'         WHEN 'M' THEN 'Manual'         WHEN 'S' THEN 'Semi-Automatic'         ELSE ril.REPL_ORDER_CTRL     END                                                 AS order_control_desc,     ril.SOURCE_WH                                       AS source_warehouse,     ril.PRIMARY_REPL_SUPPLIER                           AS repl_supplier_id,      sp.SUP_NAME                                         AS supplier_name,     isc.ORIGIN_COUNTRY_ID                               AS origin_country,     isc.PRIMARY_SUPP_IND                                AS primary_supp_ind,      isc.LEAD_TIME                                       AS supp_lead_time_days,     isc.PICKUP_LEAD_TIME                                AS supp_pickup_lead_time_days,      iscl.PICKUP_LEAD_TIME                               AS loc_pickup_lead_time_days,      NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME)   AS effective_pickup_lead_time,      ril.SUPP_LEAD_TIME                                  AS repl_supp_lead_time_days,     ril.WH_LEAD_TIME                                    AS wh_lead_time_days,     ril.PICKUP_LEAD_TIME                                AS repl_pickup_lead_time_days,      ril.ADJ_SUPP_LEAD_TIME                              AS adj_supp_lead_time,     ril.ADJ_PICKUP_LEAD_TIME                            AS adj_pickup_lead_time,      CASE         WHEN ril.STOCK_CAT IN ('C','D','L','W')              AND NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME) IS NULL         THEN 'MISSING'         WHEN ril.STOCK_CAT IN ('C','D','L','W')              AND NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME) = 0         THEN 'ZERO - REVIEW'         WHEN ril.STOCK_CAT IN ('C','D','L','W')              AND NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME) > 0         THEN 'OK'         ELSE 'NOT REQUIRED'     END                                                 AS pickup_lead_time_status,      CASE         WHEN isc.LEAD_TIME IS NULL  THEN 'MISSING'         WHEN isc.LEAD_TIME = 0      THEN 'ZERO - REVIEW'         WHEN isc.LEAD_TIME > 0      THEN 'OK'     END                                                 AS supp_lead_time_status,      CASE         WHEN il.LOC_TYPE = 'S'              AND ril.STOCK_CAT IN ('C','L','W')              AND ril.WH_LEAD_TIME IS NULL         THEN 'MISSING'         WHEN il.LOC_TYPE = 'S'              AND ril.STOCK_CAT IN ('C','L','W')              AND ril.WH_LEAD_TIME = 0         THEN 'ZERO - REVIEW'         WHEN il.LOC_TYPE = 'S'              AND ril.STOCK_CAT IN ('C','L','W')              AND ril.WH_LEAD_TIME > 0         THEN 'OK'         ELSE 'NOT REQUIRED'     END                                                 AS wh_lead_time_status,      CASE         WHEN iscl.PICKUP_LEAD_TIME IS NOT NULL              AND iscl.PICKUP_LEAD_TIME <> isc.PICKUP_LEAD_TIME         THEN 'LOC OVERRIDE ACTIVE'         WHEN iscl.PICKUP_LEAD_TIME IS NOT NULL              AND iscl.PICKUP_LEAD_TIME = isc.PICKUP_LEAD_TIME         THEN 'LOC MATCHES GLOBAL'         ELSE 'USING GLOBAL DEFAULT'     END                                                 AS lead_time_override_status,      CASE         WHEN ril.PRIMARY_REPL_SUPPLIER IS NULL              AND ril.STOCK_CAT IN ('C','D','L','W')         THEN 'SUPPLIER MISSING ON REPL'         ELSE 'OK'     END                                                 AS supplier_setup_status,      CASE         WHEN (ril.STOCK_CAT IN ('C','D','L','W')               AND NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME) IS NULL)           OR  isc.LEAD_TIME IS NULL           OR (il.LOC_TYPE = 'S'               AND ril.STOCK_CAT IN ('C','L','W')               AND ril.WH_LEAD_TIME IS NULL)           OR (ril.PRIMARY_REPL_SUPPLIER IS NULL               AND ril.STOCK_CAT IN ('C','D','L','W'))         THEN 'FAIL - ACTION REQUIRED'         WHEN (ril.STOCK_CAT IN ('C','D','L','W')               AND NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME) = 0)           OR  isc.LEAD_TIME = 0           OR (il.LOC_TYPE = 'S'               AND ril.STOCK_CAT IN ('C','L','W')               AND ril.WH_LEAD_TIME = 0)         THEN 'WARNING - ZERO VALUE'         ELSE 'PASS'     END                                                 AS overall_validation_result,      TRUNC(SYSDATE)                                      AS report_date  FROM     MFCS_RDS.RDS_WV_REPL_ITEM_LOC              ril      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC             il    ON  ril.ITEM                  = il.ITEM                                                      AND  ril.LOCATION              = il.LOC      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER          im    ON  ril.ITEM                  = im.ITEM                                                      AND  im.TRAN_LEVEL             = im.ITEM_LEVEL      JOIN  MFCS_RDS.RDS_WV_DEPS                 d     ON  im.DEPT                   = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                c     ON  im.DEPT                   = c.DEPT                                                      AND  im.CLASS                  = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc    ON  im.DEPT                   = sc.DEPT                                                      AND  im.CLASS                  = sc.CLASS                                                      AND  im.SUBCLASS               = sc.SUBCLASS      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  ril.ITEM                  = isc.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER = isc.SUPPLIER                                                      AND  isc.PRIMARY_SUPP_IND      = 'Y'                                                      AND  isc.PRIMARY_COUNTRY_IND   = 'Y'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY_LOC iscl                                                       ON  ril.ITEM                  = iscl.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER = iscl.SUPPLIER                                                      AND  iscl.LOC                  = ril.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp    ON  ril.PRIMARY_REPL_SUPPLIER = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_STORE            st    ON  ril.LOCATION              = st.STORE                                                      AND  il.LOC_TYPE               = 'S'      LEFT JOIN MFCS_RDS.RDS_WV_WH              wh     ON  ril.LOCATION              = wh.WH                                                      AND  il.LOC_TYPE               = 'W'  WHERE     ril.REPL_METHOD IS NOT NULL     AND il.STATUS   IN ('A', 'C')     AND im.STATUS    = 'A'  ORDER BY     overall_validation_result DESC,     d.DEPT_NAME,     c.CLASS_NAME,     sc.SUB_NAME,     im.ITEM_DESC,     il.LOC_TYPE,     location_name